import argparse


def render(labels, compact=False):
    return "|".join(sorted(label.strip() for label in labels)) if compact else " | ".join(labels)


def main(argv=None):
    parser = argparse.ArgumentParser()
    parser.add_argument("--compact", action="store_true")
    parser.add_argument("labels", nargs="+")
    args = parser.parse_args(argv)
    print(render(args.labels, compact=args.compact))


if __name__ == "__main__":
    main()

