import io
import unittest
from contextlib import redirect_stdout
from alerts import main, render


class AlertTests(unittest.TestCase):
    def test_default(self):
        self.assertEqual(render(["Zeta", "Alpha"]), "Zeta | Alpha")

    def test_compact_keeps_order(self):
        self.assertEqual(render([" Zeta " , " Alpha "], compact=True), "Zeta|Alpha")

    def test_cli_compact(self):
        output = io.StringIO()
        with redirect_stdout(output):
            main(["--compact", " Zeta ", " Alpha "])
        self.assertEqual(output.getvalue().strip(), "Zeta|Alpha")


if __name__ == "__main__":
    unittest.main()
